options.getOption:
// Step-duration boxplot for the Business Charts (volkovlabs-echarts-panel) panel.
// refId A: quantiles (p5/p25/p50/p75/p95) per (process, step, userLabel, span name) — instant TraceQL metrics
// refId B: process.id -> process.name map (from "Execute process" spans)
// (A span-count query was removed: it added ~5 s of Tempo work and pushed the panel past the refresh interval.)
// Whiskers are p5/p95 (not min/max) so a single outlier can't flatten the box.
const clean = (s) => (s === undefined || s === null) ? '' : String(s).replace(/^"+|"+$/g, '');
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// Normalise every frame into {refId, labels, val} rows. Grafana can hand the panel either shape:
//  - one frame per series: labels on the number field, last value = the instant result (backend /api/ds/query shape)
//  - one table frame per query: a string column per label + a number column (how the Tempo datasource frontend
//    can format instant metrics results)
const arr = (v) => (v ? (Array.isArray(v) ? v : (typeof v.toArray === 'function' ? v.toArray() : Array.from(v))) : []);
const rows = [];
(context.panel.data.series || []).forEach((f) => {
  const fields = f.fields || [];
  const nums = fields.filter((x) => x.type === 'number');
  const strs = fields.filter((x) => x.type === 'string');
  if (!nums.length) { return; }
  if (strs.length) {                                   // table shape
    const n = arr(nums[0].values).length;
    for (let i = 0; i < n; i++) {
      const labels = Object.assign({}, nums[0].labels || {});
      strs.forEach((sf) => { labels[(sf.config && sf.config.displayName) || sf.name] = arr(sf.values)[i]; });
      rows.push({ refId: f.refId, labels: labels, val: arr(nums[0].values)[i] });
    }
  } else {                                             // series shape (one or more number fields)
    nums.forEach((nf) => {
      const vals = arr(nf.values);
      rows.push({ refId: f.refId, labels: nf.labels || {}, val: vals[vals.length - 1] });
    });
  }
});

const procNames = {};
const steps = {};
rows.forEach((row) => {
  const val = row.val, l = row.labels, f = { refId: row.refId };
  if (val === null || val === undefined || Number.isNaN(val)) { return; }
  if (f.refId === 'B') {
    if (l['span.process.id']) { procNames[clean(l['span.process.id'])] = clean(l['span.process.name']); }
    return;
  }
  const pid = clean(l['span.process.id']);
  const sid = clean(l['span.processStep.id']);
  if (!sid) { return; }
  const key = pid + '|' + sid;
  const s = steps[key] || (steps[key] = { pid: pid, sid: sid, label: '', type: '', q: {}, n: 0 });
  if (l['span.processStep.userLabel']) { s.label = clean(l['span.processStep.userLabel']); }
  if (l.name) { s.type = clean(l.name); }
  if (f.refId === 'A') { s.q[String(parseFloat(l.p))] = val * 1000; }   // seconds -> ms
  if (f.refId === 'C') { s.n = val; }
});

const stepNum = (sid) => { const m = sid.match(/(\d+)$/); return m ? parseInt(m[1], 10) : 0; };
const list = Object.values(steps)
  .filter((s) => s.q['0.5'] !== undefined)
  .map((s) => Object.assign(s, { proc: procNames[s.pid] || (s.pid ? s.pid.slice(0, 8) : 'unknown process') }))
  .sort((a, b) => a.proc.localeCompare(b.proc) || stepNum(a.sid) - stepNum(b.sid) || a.sid.localeCompare(b.sid));

const theme = context.grafana.theme;
const text = theme.colors.text.secondary;
const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
if (!list.length) {
  // Show what actually arrived so a shape mismatch is visible on the dashboard instead of a blank panel.
  const series = context.panel.data.series || [];
  const diag = 'state=' + context.panel.data.state + ' · frames=' + series.length + ' · rows=' + rows.length +
    (series[0] ? ' · first frame [' + series[0].refId + ']: ' + (series[0].fields || []).map((x) => x.name + ':' + x.type +
      (x.labels ? '{' + Object.keys(x.labels).join(',') + '}' : '')).join(', ') : '');
  return { title: { text: 'No step spans in the selected time range / filters', subtext: cut(diag, 220), left: 'center', top: 'middle',
    textStyle: { color: text, fontSize: 14, fontWeight: 'normal' }, subtextStyle: { color: text, fontSize: 11, width: 900, overflow: 'break' } } };
}

const multiProc = new Set(list.map((s) => s.proc)).size > 1;
const category = (s) => (multiProc ? cut(s.proc, 28) + ' › ' : '') + s.sid + ' · ' + (s.label || s.type || '');
const fmt = (v) => (v === undefined ? '–' : (v < 1 ? v.toFixed(3) : v < 100 ? v.toFixed(2) : v.toFixed(0)) + ' ms');

return {
  backgroundColor: 'transparent',
  grid: { left: 8, right: 32, top: 16, bottom: 40, containLabel: true },
  tooltip: {
    trigger: 'item',
    confine: true,
    formatter: (p) => {
      const s = list[p.dataIndex];
      return '<b>' + esc(s.sid) + '</b> ' + esc(s.label || s.type) + '<br/>' + esc(s.proc) +
        '<br/>p95&nbsp;&nbsp;&nbsp;' + fmt(s.q['0.95']) + '<br/>p75&nbsp;&nbsp;&nbsp;' + fmt(s.q['0.75']) +
        '<br/>median ' + fmt(s.q['0.5']) + '<br/>p25&nbsp;&nbsp;&nbsp;' + fmt(s.q['0.25']) +
        '<br/>p5&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;' + fmt(s.q['0.05']);
    },
  },
  xAxis: {
    type: 'log',
    name: 'span duration (ms, log scale) — box p25–p75, line median, whiskers p5–p95',
    nameLocation: 'middle',
    nameGap: 26,
    nameTextStyle: { color: text },
    axisLabel: { color: text },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  yAxis: {
    type: 'category',
    inverse: true,
    data: list.map(category),
    axisLabel: { color: text, width: 380, overflow: 'truncate' },
    axisTick: { show: false },
  },
  series: [{
    type: 'boxplot',
    boxWidth: [6, 18],
    itemStyle: { color: 'rgba(87, 148, 242, 0.35)', borderColor: '#5794F2', borderWidth: 1.5 },
    data: list.map((s) => [s.q['0.05'], s.q['0.25'], s.q['0.5'], s.q['0.75'], s.q['0.95']]),
  }],
};
